function form_start(string $action): void { echo '<form method="post"><input type="hidden" name="csrf" value="'.h(csrf()).'"><input type="hidden" name="action" value="'.h($action).'">'; }
function hidden(string $name,mixed $value): void { echo '<input type="hidden" name="'.h($name).'" value="'.h($value).'">'; }
function field(string $label,string $name,mixed $value='',string $type='text',bool $required=true): void { echo '<label>'.h($label).'<input type="'.h($type).'" name="'.h($name).'" value="'.h($value).'" '.($required?'required ':'').($type==='datetime-local'?'step="1"':'').'></label>'; }
function select_field(string $label,string $name,array $options,mixed $selected=''): void { echo '<label>'.h($label).'<select name="'.h($name).'">'; foreach($options as $v=>$text) echo '<option value="'.h($v).'" '.((string)$v===(string)$selected?'selected':'').'>'.h($text).'</option>'; echo '</select></label>'; }
